use vstd::prelude::*;

verus! {

/// Returns the index of the first occurrence of the maximum element in a non-empty `Vec<i8>`.
///  
/// Requires:
///   - `a.len() > 0`
/// Ensures:
///   - `idx < a.len()`
///   - For all `j < a.len()`, `a[idx] >= a[j]`
///   - If `a[j] == a[idx]`, then `idx <= j` (i.e., the first occurrence).
fn nanargmax(a: Vec<i8>) -> (idx: usize)
    requires
        a.len() > 0,
    ensures
        idx < a.len(),
        forall |j: usize| j < a.len() ==> a[idx] >= a[j],
        forall |j: usize| j < a.len() && a[j] == a[idx] ==> idx <= j,
{
    let n = a.len();
    // We will scan from 1 to n-1, maintaining `best` as the index of the
    // maximum element seen so far, and `i` as the next index to inspect.
    let mut best: usize = 0;
    let mut i: usize = 1;
    while i < n
        invariant
            // Bounds
            i <= n,
            best < i,
            // `best` is a max over [0..i)
            forall |j: usize| j < i ==> a[best] >= a[j],
            // `best` is the *first* max over [0..i)
            forall |j: usize| j < i && a[j] == a[best] ==> best <= j,
        decreases n - i,
    {
        // If the current element is strictly greater, update `best`.
        if a[i] > a[best] {
            best = i;
        }
        // Move on to the next element.
        i = i + 1;
    }
    // At this point, `i == n`, so `best < n` and the invariants give:
    //   - for all j < n, a[best] >= a[j]
    //   - if a[j] == a[best], then best <= j
    best
}

}

